:root {
  --navy: #0a0a23;
  --charcoal: #121223;
  --accent: #d6a536;
  --accent-soft: #f5e4b9;
  --text: #1c2230;
  --muted: #6a7280;
  --bg: #ffffff;
  --light: #f7f8fb;
  --border: #e8ebf1;
  --radius: 14px;
  --shadow: 0 12px 30px rgba(7, 10, 30, 0.08);
}
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
  line-height: 1.55;
}
a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
.container { width: min(1120px, 92vw); margin: 0 auto; }
.site-header {
  background: var(--navy);
  color: #fff;
  position: sticky;
  top: 0;
  z-index: 20;
}
.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 72px;
}
.brand { font-weight: 800; letter-spacing: 0.2px; font-size: 1.1rem; }
.brand span { color: var(--accent); }
.nav-links { display: flex; gap: 1.1rem; align-items: center; }
.nav-links a { color: #d8def4; font-weight: 500; }
.nav-links a:hover, .nav-links a.active { color: #fff; }
.menu-btn {
  display: none;
  background: transparent;
  border: 1px solid #2d355d;
  color: #fff;
  border-radius: 10px;
  padding: 0.4rem 0.65rem;
}
.mobile-menu {
  display: none;
  flex-direction: column;
  gap: 0.8rem;
  padding: 0 0 1rem;
}
.mobile-menu a { color: #e7ebff; }
.hero {
  padding: 3.2rem 0 2rem;
  background: linear-gradient(180deg, #f9fafc 0%, #ffffff 100%);
}
.hero h1 { margin: 0 0 0.7rem; font-size: clamp(1.8rem, 3.5vw, 2.9rem); line-height: 1.15; }
.hero p { color: var(--muted); max-width: 760px; margin: 0; }
.section-title {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: 1rem;
  margin: 2rem 0 1rem;
}
.section-title h2 { margin: 0; font-size: 1.4rem; }
.section-title p { margin: 0; color: var(--muted); }
.grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 1.15rem;
}
.card {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: #fff;
  overflow: hidden;
  box-shadow: var(--shadow);
}
.card img { height: 170px; width: 100%; object-fit: cover; }
.card-body { padding: 1rem; }
.tag {
  display: inline-block;
  font-size: 0.77rem;
  font-weight: 700;
  padding: 0.22rem 0.55rem;
  border-radius: 999px;
  background: var(--accent-soft);
  color: #7b5600;
}
.card h3 {
  margin: 0.65rem 0 0.8rem;
  font-size: 1.04rem;
  line-height: 1.35;
}
.meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--muted);
  font-size: 0.9rem;
}
.author { display: flex; align-items: center; gap: 0.5rem; }
.avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--navy);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 0.78rem;
  font-weight: 700;
}
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 12px;
  background: var(--accent);
  color: #271900;
  font-weight: 700;
  padding: 0.72rem 1.1rem;
  cursor: pointer;
}
.center { text-align: center; margin: 1.5rem 0 2.8rem; }
.list-panel, .stat-panel {
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.1rem 1.2rem;
  background: #fff;
  box-shadow: var(--shadow);
}
.list-panel + .list-panel, .stat-panel + .stat-panel { margin-top: 1rem; }
.curriculum-item { display: flex; gap: 0.7rem; align-items: flex-start; padding: 0.75rem 0; border-bottom: 1px solid var(--border); }
.curriculum-item:last-child { border-bottom: 0; }
.icon-badge {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: #ebf0ff;
  color: #1f3a8a;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
}
.donate-layout {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: 1rem;
}
.amount-tabs { display: flex; flex-wrap: wrap; gap: 0.6rem; margin: 1rem 0; }
.amount-btn {
  border: 1px solid var(--border);
  background: #fff;
  color: var(--text);
  border-radius: 10px;
  padding: 0.55rem 0.95rem;
  font-weight: 700;
  cursor: pointer;
}
.amount-btn.active { background: var(--accent); border-color: #c58f1f; color: #2b1d00; }
.faq-item { border-top: 1px solid var(--border); }
.faq-q {
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  padding: 0.9rem 0;
  font-weight: 700;
  cursor: pointer;
}
.faq-a {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.25s ease;
  color: var(--muted);
}
.faq-item.open .faq-a { max-height: 120px; padding-bottom: 0.8rem; }
.tag-row { display: flex; gap: 0.6rem; overflow: auto; padding-bottom: 0.2rem; }
.tag-pill { white-space: nowrap; border: 1px solid var(--border); border-radius: 999px; padding: 0.4rem 0.7rem; font-size: 0.87rem; background: #fff; }
footer {
  margin-top: 2.5rem;
  padding: 1.3rem 0;
  color: #c8cde0;
  background: var(--charcoal);
  font-size: 0.92rem;
}
@media (max-width: 980px) {
  .grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .donate-layout { grid-template-columns: 1fr; }
}
@media (max-width: 760px) {
  .nav-links { display: none; }
  .menu-btn { display: inline-flex; }
  .mobile-menu.show { display: flex; }
  .grid { grid-template-columns: 1fr; }
}
EOF

